/** EB Garamond (latin, 400) embedded for server-rendered Open Graph images. */
export const OG_FONT_REGULAR_BASE64 = "";
export const OG_FONT_ITALIC_BASE64 = "";

export function decodeFont(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}
